import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';

let child,base,dir;
test.before(async()=>{dir=await mkdtemp(join(tmpdir(),'patchpad-'));const port=31000+Math.floor(Math.random()*1000);base=`http://127.0.0.1:${port}`;child=spawn(process.execPath,['server.js'],{cwd:new URL('..',import.meta.url),env:{...process.env,PORT:String(port),DATABASE_PATH:join(dir,'test.sqlite')},stdio:['ignore','pipe','pipe']});await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('server timeout')),5000);child.stdout.on('data',()=>{clearTimeout(timer);resolve()});child.once('exit',code=>reject(new Error(`server exited ${code}`)))})});
test.after(async()=>{child?.kill();await rm(dir,{recursive:true,force:true})});
const request=async(path,options)=>{const response=await fetch(base+path,options);return{response,data:await response.json()}};
test('seed creates one exact long document and initial revision',async()=>{const list=await request('/api/documents');assert.equal(list.data.length,1);const {data:doc}=await request('/api/documents/incident-alpha');assert.equal(doc.revision,1);assert.equal(doc.metadata.generatedLineCount,1200);assert.match(doc.content,/Log line 0001:/);assert.match(doc.content,/Log line 1200:/);assert.ok(doc.content.endsWith('The editor must preserve this tail sentinel: OMEGA-END-ANCHOR.'));const revisions=await request('/api/documents/incident-alpha/revisions');assert.equal(revisions.data.length,1)});
test('save, unchanged save, and stale save preserve revision safety',async()=>{const {data:doc}=await request('/api/documents/incident-alpha');const save={method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({id:doc.id,baseRevision:1,content:doc.content+'\nchange'})};let result=await request('/api/documents/incident-alpha',save);assert.equal(result.response.status,200);assert.equal(result.data.revision,2);result=await request('/api/documents/incident-alpha',{...save,body:JSON.stringify({id:doc.id,baseRevision:2,content:doc.content+'\nchange'})});assert.equal(result.data.unchanged,true);result=await request('/api/documents/incident-alpha',save);assert.equal(result.response.status,409);const current=await request('/api/documents/incident-alpha');assert.equal(current.data.revision,2);assert.ok(current.data.content.endsWith('\nchange'));const revisions=await request('/api/documents/incident-alpha/revisions');assert.equal(revisions.data.length,2)});
test('malformed, mismatched, and unknown saves cannot mutate content',async()=>{const before=(await request('/api/documents/incident-alpha')).data;for(const [path,body] of [['/api/documents/incident-alpha',{id:'other',baseRevision:2,content:'bad'}],['/api/documents/incident-alpha',{id:'incident-alpha',content:'bad'}],['/api/documents/incident-alpha',{id:'incident-alpha',baseRevision:'2',content:'bad'}],['/api/documents/incident-alpha',{id:'incident-alpha',baseRevision:2,content:42}],['/api/documents/missing',{id:'missing',baseRevision:1,content:'bad'}]]){const result=await request(path,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)});assert.ok(result.response.status>=400)}const malformed=await fetch(base+'/api/documents/incident-alpha',{method:'PUT',headers:{'content-type':'application/json'},body:'{' });assert.equal(malformed.status,400);const after=(await request('/api/documents/incident-alpha')).data;assert.equal(after.revision,before.revision);assert.equal(after.content,before.content)});
